    vm_pop_num(task, &rec); fh = gmb_task_pop(task);
    long hh = fh.type == 1 ? (long)fh.num : 0; if (fh.ref) gmb_obj_release(fh.ref);
    int rc = gmb_file_lock(hh, rec, 1);
