                            gmb_dict_set(pd->dict, "FormFields", gmb_make_val_obj((gmb_obj_t*)fieldsObj));
                            gmb_dict_set(pd->dict, "FileFields", gmb_make_val_obj((gmb_obj_t*)filesObj));
                            push_ref_new(task, (gmb_obj_t*)pd, GMB_BT_OBJECT);
